const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function pollOrderStatus(orderId, signal) {
  while (!signal.aborted) {
    const status = await fetchStatus(orderId); // ~300 ms
    renderStatus(status);
    if (status === 'delivered') return;
    await sleep(10000);
  }
}

The user opens order #1 at t = 0. The first status is rendered at t = 0.3 s. At t = 2 s they open order #2, and the page calls controller.abort() for order #1. What happens to the first loop?
